  const n = points.length;
  const isPoint = (i) => points[i].length >= 2;
  let best = 0;
  for (let i = 0; i < n; i++) {
    if (!isPoint(i)) continue;
    let same = 0;
    for (let j = 0; j < n; j++) {
      if (!isPoint(j)) continue;
      if (points[i][0] === points[j][0] && points[i][1] === points[j][1]) same++;
    }
    if (same > best) best = same;
  }
  for (let i = 0; i < n; i++) {
    if (!isPoint(i)) continue;
    for (let j = i + 1; j < n; j++) {
      if (!isPoint(j)) continue;
      const dx = points[j][0] - points[i][0];
      const dy = points[j][1] - points[i][1];
      if (dx === 0 && dy === 0) continue;
      let count = 0;
      for (let k = 0; k < n; k++) {
        if (!isPoint(k)) continue;
        const cross = dx * (points[k][1] - points[i][1]) - dy * (points[k][0] - points[i][0]);
        if (cross === 0) count++;
      }
      if (count > best) best = count;
    }
  }
  return best;
}

function solve(points) {
  const n = points.length;
  const isPoint = (i) => points[i].length >= 2;
  const gcd = (a, b) => {
    while (b !== 0) {
      const rest = a % b;
      a = b;
      b = rest;
    }
    return a;
  };
  let best = 0;
  for (let i = 0; i < n; i++) {
    if (!isPoint(i)) continue;
    const xi = points[i][0];
    const yi = points[i][1];
    const groups = new Map();
    let same = 1;
    let widest = 0;
    for (let j = i + 1; j < n; j++) {
      if (!isPoint(j)) continue;
      let dx = points[j][0] - xi;
      let dy = points[j][1] - yi;
      if (dx === 0 && dy === 0) {
        same++;
        continue;
      }
      const g = gcd(Math.abs(dx), Math.abs(dy));
      dx = dx / g;
      dy = dy / g;
      if (dx < 0 || (dx === 0 && dy < 0)) {
        dx = -dx;
        dy = -dy;
      }
      const key = dx + ',' + dy;
      const count = (groups.get(key) || 0) + 1;
      groups.set(key, count);
      if (count > widest) widest = count;
    }
    const total = same + widest;
    if (total > best) best = total;
  }
  return best;
}
